insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$شراء الفضلة العقارية (بيع الفضلات للعقارات الملاصقة)$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: قانون الاستملاك 91/58 (م.27 و28 و53)؛ قانون البناء 646/2004 م.5 و8؛ القرار 275/1926 م.77 و80 و83؛ قانون التنظيم المدني 83/69 م.18؛ قانون البلديات م.60–62.$q$,$q$[{"ar": "طلب خطي من مالك العقار المجاور (تثبت ملكيته بتاريخ الدعوى)"}, {"ar": "إفادة عقارية حديثة للعقار الملاصق للفضلة"}, {"ar": "خريطة موقع للفضلة ومشروع ضم موقع من مساح محلف"}, {"ar": "صور فوتوغرافية للموقع"}, {"ar": "إفادة عقارية للفضلة وإفادة تخطيط وارتفاق (حسب نموذج الطلب الرسمي في S10)"}]$q$::jsonb,$q$[{"ar": "تقديم المالك المجاور طلباً إلى البلدية يطلب فيه إسقاط الفضلة إلى الأملاك الخصوصية ليتمكن من شرائها"}, {"ar": "درس البلدية الموضوع قانونياً وقرار المجلس البلدي بالموافقة على الإسقاط (بالإجماع أو بالأكثرية)"}, {"ar": "إحالة الملف كاملاً إلى وزارة الداخلية والبلديات (المديرية العامة للإدارات والمجالس المحلية) للدرس القانوني والفني وموافقة وزير الداخلية (م.62 بلديات: إسقاط الأملاك البلدية العامة إلى خاصة)"}, {"ar": "تقديم ملف الإسقاط إلى أمين السجل العقاري: دائرة المساحة تنظم خريطة جديدة وتعطي الفضلة رقماً جديداً، وتفتح لها صحيفة وسند ملكية باسم أملاك البلدية الخاصة"}, {"ar": "تخمين الفضلة من لجنة الخبراء (م.80 و83 من القرار 275/1926) بالسعر الرائج؛ وعند الخلاف تفصل لجان الاستملاك الاستئنافية"}, {"ar": "قرار المجلس البلدي بالبيع بالتراضي من المالك المجاور بالسعر المقدر، مع تفويض رئيس البلدية أو نائبه أو محامي البلدية بتوقيع العقد، ويخضع لتصديق القائمقام أو المحافظ بحسب قيمة العقار (م.60 و61)"}, {"ar": "عند تمنع المجاورين عن الشراء: بيع بالمزايدة العلنية محصورة بين أصحاب العقارات الملاصقة، أو مقايضة، أو قيام الإدارة بالشراء (م.18 تنظيم مدني)"}, {"ar": "تنظيم عقد البيع أمام الكاتب العدل أو رئيس المكتب العقاري المعاون، بعد موافقة ديوان المحاسبة المسبقة عند تجاوز الحد المقرر وكون البلدية خاضعة لرقابته"}, {"ar": "تقديم العقد مع سند الملكية ومحضر التخمين وقرار المجلس إلى المكتب العقاري، وبعد تصديق أمين السجل العقاري يقيد في سجل الملكية باسم المشتري"}, {"ar": "عقد ضم الفضلة إلى العقار الأساسي ودفع الرسوم الفنية وتكليف دائرة المساحة؛ وإن وجد مانع من الضم تبقى الفضلة وحدة عقارية مع العقار الأساسي (م.8 قانون البناء 2004)"}]$q$::jsonb,$q$البلدية / لجنة خبراء$q$,null,null from municipal_service where slug=$q$t-135$q$ on conflict (service_id,version_no) do nothing;
insert into service_source (version_id,title,kind) select v.id,$q$كتالوج BALADI ONE — مسودة قيد المراجعة القانونية$q$,'internal' from service_version v join municipal_service s on s.id=v.service_id where s.slug=$q$t-135$q$ and v.version_no=1 and not exists (select 1 from service_source z where z.version_id=v.id and z.kind='internal');
insert into service_source (version_id,title,kind) select v.id,$q$قانون الاستملاك 91/58 (م.27 و28 و53)؛ قانون البناء 646/2004 م.5 و8؛ القرار 275/1926 م.77 و80 و83؛ قانون التنظيم المدني 83/69 م.18؛ قانون البلديات م.60–62$q$,'law' from service_version v join municipal_service s on s.id=v.service_id where s.slug=$q$t-135$q$ and v.version_no=1 and not exists (select 1 from service_source z where z.version_id=v.id and z.title=$q$قانون الاستملاك 91/58 (م.27 و28 و53)؛ قانون البناء 646/2004 م.5 و8؛ القرار 275/1926 م.77 و80 و83؛ قانون التنظيم المدني 83/69 م.18؛ قانون البلديات م.60–62$q$);
