insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$المشاركة في مناقصة أو استدراج عروض بلدي (متعهد / تاجر)$q$,$q$الفئة: مشتريات. الأساس القانوني: قانون البلديات م.53–55 وم.57–58؛ مرسوم أصول المحاسبة في البلديات 82/5595؛ قانون المحاسبة العمومية 63/14969؛ مرسوم نظام المناقصات 2866/1959.$q$,$q$[{"ar": "تعهد خطي بالتقيد بكل بنود دفتر الشروط دون قيد أو شرط، متضمناً: عدم صدور قرار إقصاء بحق مقدم العرض عن الصفقات العامة، التقيد بمرسوم السلامة العامة، عنوان إقامة مختار ضمن النطاق البلدي للتبليغ"}, {"ar": "نسخة مصدقة عن شهادة تسجيل المؤسسة، أو شهادة تسجيل الشركة مع عقد الشراكة"}, {"ar": "براءة ذمة بلدية (من البلدية التي تنفذ فيها الأشغال)"}, {"ar": "براءة ذمة من الضمان الاجتماعي"}, {"ar": "تأمين مؤقت بكفالة مصرفية من مصرف معترف به، صالحة ثلاثة أشهر على الأقل من تاريخ المناقصة (لا يجوز الاستعاضة عنها بمبلغ نقدي عند فض العروض)"}, {"ar": "إيصال من صندوق البلدية بسداد ثمن دفتر الشروط"}, {"ar": "بوليصة تأمين على الأشغال تجاه عمال المتعهد وآلياته والمواطنين وسياراتهم"}, {"ar": "إفادة تصنيف لدى وزارة الأشغال العامة (لأشغال الطرق) من الدرجة المطلوبة"}, {"ar": "ملكية معدات مسجلة باسم العارض أو عقود استئجارها"}, {"ar": "إفادة انتساب إلى نقابة المقاولين وبراءة ذمة مالية صادرة عنها"}, {"ar": "الرقم المالي إلزامي لمن يقدم عرض أسعار (شركة أو مؤسسة)"}]$q$::jsonb,$q$[{"ar": "حاجة البلدية: طلب خطي مسجل في قلم البلدية يرفع إلى رئيس البلدية، ثم قرار المجلس البلدي بالموافقة على دفتر الشروط ويخضع لتصديق سلطة الرقابة"}, {"ar": "الإعلان عن المناقصة على لوحة إعلانات البلدية وفي الجريدة الرسمية وفي ثلاث صحف يومية من بينها صحف النطاق البلدي، قبل 15 يوماً على الأقل من جلسة التلزيم (تخفض إلى 5 أيام عند إعادة المناقصة أو الضرورة بموافقة المرجع الصالح)"}, {"ar": "الحصول على دفتر الشروط ثم إعداد العرض في ظرف خارجي يحوي ظرفين: ملف المستندات وملف عرض الأسعار، دون أي إشارة تدل على هوية مقدم العرض"}, {"ar": "تقديم العرض في قلم البلدية ضمن المهلة المحددة (إذا صادف آخر المهلة عطلة رسمية امتدت إلى أول يوم عمل)"}, {"ar": "جلسة لجنة المناقصات: التأكد من ورود العروض ضمن المهل؛ إن لم يرد عرض أو ورد عرض واحد تعاد المناقصة؛ عند وجود عارضين على الأقل تفض العروض في الجلسة نفسها وتتلى محتوياتها علناً"}, {"ar": "إسناد الالتزام مؤقتاً لصاحب العرض الأفضل وتنظيم محضر موقع من الرئيس والعضوين"}, {"ar": "عرض المحضر على المجلس البلدي للموافقة بقرار يخضع لتصديق سلطة الرقابة، ويتضمن تكليف رئيس البلدية بالتوقيع أو إبلاغ المتعهد تصديق الالتزام"}, {"ar": "تبليغ المتعهد التصديق، وتقديم التأمين النهائي خلال 5 أيام من التبليغ وإلا اعتبر ناكلاً وصودر التأمين المؤقت وأعيد التلزيم على نفقته"}, {"ar": "تسلم مواقع العمل بمحضر، ثم تنفيذ الأشغال وفق الكميات الملحوظة دون تجاوزها إلا بإذن خطي"}]$q$::jsonb,$q$لجنة المناقصات البلدية (رئيس البلدية ونائبه وعضوان أصليان وعضوان رديفان) / المجلس البلدي / سلطة الوصاية$q$,null,$q$إعلان المناقصة: 15 يوماً على الأقل (5 أيام عند الإعادة أو الضرورة) / الالتزام بالعرض: 60 يوماً من موافقة آخر سلطة رقابة / التأمين النهائي: خلال 5 أيام من تبليغ التصديق$q$ from municipal_service where slug=$q$t-136$q$ on conflict (service_id,version_no) do nothing;
