insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$المشاركة في مزايدة لاستثمار أو استئجار عقار ملك للبلدية$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: قانون البلديات م.49 و53 و60–61؛ دفتر شروط المزايدة المنظم بقرار المجلس البلدي.$q$,$q$[{"ar": "طلب اشتراك خطي مع تعهد بالتقيد بدفتر الشروط"}, {"ar": "كفالة مالية للاشتراك في المزايدة تعاد لمن لم يرس عليه الالتزام بعد تصديق محضر التلزيم"}, {"ar": "المستندات التعريفية حسب دفتر الشروط"}]$q$::jsonb,$q$[{"ar": "إعداد دفتر شروط المزايدة وتصديقه بقرار المجلس البلدي وفق الأصول"}, {"ar": "الإعلان عن المزايدة العامة في الجريدة الرسمية وفي ثلاث صحف محلية"}, {"ar": "تقديم العروض وانعقاد لجنة المناقصات؛ تحال الصفقة إلى صاحب أعلى سعر ويحق للمجلس رفض أي عرض لا يراه مناسباً لمصلحة البلدية"}, {"ar": "عند تساوي عدة مزايدين في السعر تعاد المزايدة فوراً بينهم دون سواهم"}, {"ar": "تصديق محضر التلزيم من المرجع المختص ثم تبليغ المستثمر ودعوته لتسلم العقار بمحضر على نسختين يوقعه المستأجر ورئيس البلدية"}, {"ar": "عند عدم نجاح المزايدة العامة: الاتفاق بالتراضي مع راغب خطياً بالتقيد بدفتر الشروط، ويعمل بالعقد بعد موافقة المراجع المختصة"}, {"ar": "تسديد بدل الاستثمار مسبقاً لدى صندوق البلدية، ثم تنفيذ الالتزامات (الصيانة والحراسة والرخص اللازمة لوجهة الاستعمال)"}]$q$::jsonb,$q$لجنة المناقصات البلدية / المجلس البلدي / سلطة الوصاية$q$,null,null from municipal_service where slug=$q$t-137$q$ on conflict (service_id,version_no) do nothing;
