insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$عقار مصاب بتخطيط أو استملاك بلدي: حقوق المالك ومراحل المعاملة$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: قانون الاستملاك 91/58 (م.1 و2 و8 و22 و26 و27 و28 و35 و41–43)؛ قانون التنظيم المدني 83/69 (م.9 و11 و17 و18)؛ قانون البلديات م.49 بند 12 وم.51.$q$,$q$[{"ar": "مستندات إثبات الملكية أو الحق العيني على العقار"}, {"ar": "للمستأجر والمستثمر: سند ذو تاريخ صحيح أو وثيقة رسمية يثبت أن الحق نشأ قبل قيد إشارة المرسوم على صحيفة العقار (أو قبل النشر في الجريدة الرسمية لغير الممسوح)"}]$q$::jsonb,$q$[{"ar": "صدور مرسوم إعلان المنفعة العامة أو مرسوم التخطيط بناءً على طلب البلدية، وينشر ويعين المدة القصوى لبدء معاملات الاستملاك (لا تتجاوز ثماني سنوات)"}, {"ar": "تخمين العقار وتحديد التعويض من لجنة الاستملاك البدائية؛ ولا يقبل قرارها إلا الاستئناف أمام لجنة الاستملاك الاستئنافية"}, {"ar": "إيداع كامل التعويض فور تبلغ القرار وإعلام صاحب التعويض ثم استصدار قرار وضع اليد (والاستئناف لا يوقف المعاملات)"}, {"ar": "إذا مرت ستة أشهر على التبليغ دون إيداع تستحق الفائدة القانونية؛ وإذا جاوز التأخير سنتين فللمستحق طلب إعادة التخمين بالأسعار الرائجة"}, {"ar": "إن لم تباشر الإدارة التنفيذ خلال ثلاث سنوات من مرسوم التخطيط يعتبر الإعلان كأنه لم يكن، ويمكن للمعني طلب ترقين القيود من أمين السجل العقاري، ولا يعاد استملاك العقار للغرض ذاته قبل عشر سنوات"}]$q$::jsonb,$q$البلدية / لجنة الاستملاك البدائية والاستئنافية / مجلس الوزراء / القضاء الإداري$q$,null,$q$سقوط مرسوم التخطيط إن لم يُباشر التنفيذ خلال 3 سنوات / إيداع التعويض: فائدة بعد 6 أشهر وإعادة تخمين بعد سنتين من التبليغ$q$ from municipal_service where slug=$q$t-138$q$ on conflict (service_id,version_no) do nothing;
