insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الإشغال المؤقت لعقار خاص لأشغال عامة (للمالك أو الشاغل)$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: قانون الاستملاك 91/58 م.35 و41–43.$q$,$q$[]$q$::jsonb,$q$[{"ar": "حالة أرض غير مبنية مصابة بتخطيط: خلال خمس سنوات من نشر المرسوم تنفذ الإدارة الأشغال بعد موافقة مجلس الوزراء المسبقة وتحيل الملف إلى لجنة الاستملاك لتحديد بدل الإشغال السنوي، ويودع قبل الإشغال ويبقى العقار مسجلاً باسم مالكه"}, {"ar": "حالة عقار غير مصاب بتخطيط: ترخيص مسبق يعين الأعمال والعقارات والطريق ونوع الإشغال ومدته؛ يحظر إشغال الساحات والحدائق والبساتين المتصلة ببيوت السكن إذا كانت مسورة"}, {"ar": "تحديد التعويض من السلطة التي أصدرت القرار وإيداعه قبل الإشغال، ويشمل الأضرار الناجمة"}, {"ar": "تنفيذ الاستملاك الناجم عن التخطيط خلال مهلة لا تزيد عن ثلاث عشرة سنة من نشر المرسوم"}]$q$::jsonb,$q$السلطة المرخصة (وزير الأشغال العامة والنقل / مجلس الوزراء) / لجنة الاستملاك$q$,null,$q$الترخيص يسقط بعد 6 أشهر دون مباشرة؛ الحد الأقصى للإشغال 3 سنوات$q$ from municipal_service where slug=$q$t-139$q$ on conflict (service_id,version_no) do nothing;
