insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إجازة إفراز عقار (تقسيم إلى قطع)$q$,$q$الفئة: التنظيم المدني. الأساس القانوني: قانون التنظيم المدني 83/69 (م.27 وما يليها)؛ قانون البناء 646/2004؛ نظام المنطقة.$q$,$q$[{"ar": "تصاميم الإفراز موضوعة وفق النصوص النافذة للتنظيم المدني، خاصة المساحات الدنيا للقطع في الأماكن الآهلة"}, {"ar": "شبكة طرق ملائمة؛ وللمشاريع الكبيرة: فسحات حرة مشجرة وشبكات إنارة ومياه شرب وتصريف مياه مستعملة"}, {"ar": "التقيد بشروط السلامة العامة والصحة العامة واحترام المناظر الطبيعية"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب مع التصاميم إلى السلطة المختصة"}, {"ar": "صدور قرار الإجازة بالإفراز ويسجل حكماً في الصحيفة العينية للعقار"}, {"ar": "المباشرة بعمليات الإفراز خلال سنة من تسليم الإجازة وإنجازه ضمن المهلة المحددة في القرار (لا تتجاوز عشر سنوات) وإلا سقطت الإجازة"}, {"ar": "بعد الإنجاز: شهادة مطابقة من الإدارة تثبت تنفيذ الإفراز وتجهيزاته وفق التصاميم، فتصبح القطع الجديدة قابلة لجميع الأعمال التصرفية"}, {"ar": "استبدال الضمانات والحقوق العينية على العقار القديم بحقوق موازية، وللمعنيين الاعتراض إن أُجحفوا"}]$q$::jsonb,$q$السلطة الإدارية المختصة (التنظيم المدني) مع رأي البلدية$q$,null,$q$المباشرة خلال سنة من تسليم الإجازة؛ الإنجاز خلال المهلة المحددة (حد أقصى 10 سنوات)$q$ from municipal_service where slug=$q$t-142$q$ on conflict (service_id,version_no) do nothing;
