insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الضم والفرز في الأماكن الآهلة (من المالكين أو البلدية)$q$,$q$الفئة: التنظيم المدني. الأساس القانوني: المرسوم الاشتراعي 83/70؛ قانون التنظيم المدني 83/69 م.20.$q$,$q$[]$q$::jsonb,$q$[{"ar": "طلب الضم والفرز من الإدارات أو البلدية أو المالكين لأحد الأغراض: التجميل والتوسع، تقسيم جديد للأحياء القديمة، إعادة بناء الأحياء المخربة، شق طرق مصدقة، مناطق سكنية جديدة، تنفيذ التصميم التوجيهي، تعديل الحدود بين عقارين أو أكثر"}, {"ar": "درس المشروع وتحديد النطاق من المديرية العامة للتنظيم المدني، ثم مرسوم بإجراء الضم والفرز بناءً على اقتراح وزير الأشغال العامة والنقل، ينشر ويعلق في مركز البلدية أو المختار ويبلغ إلى السجل العقاري لوضع إشارته"}, {"ar": "تخمين العقارات بحالتها الحاضرة، ثم الضم والفرز الجديد، ثم تخمين القطع الجديدة مع مراعاة التحسين، ثم توزيعها على المالكين تحت إشراف القاضي المشرف"}, {"ar": "إنجاز الأعمال في مرحلتي التخمين خلال سنتين من إعلان القاضي افتتاح الأعمال، قابلة للتمديد سنتين مرة واحدة بقرار وزير الأشغال"}]$q$::jsonb,$q$المديرية العامة للتنظيم المدني / مرسوم / القاضي العقاري المشرف / لجنة الضم والفرز$q$,null,$q$إنجاز مرحلتي التخمين خلال سنتين من افتتاح الأعمال (تمديد سنتين مرة واحدة)$q$ from municipal_service where slug=$q$t-143$q$ on conflict (service_id,version_no) do nothing;
