insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب ضم طريق خاص إلى الملك العام البلدي$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: القانون 388/2001 (تعديل القانون 89/3) في ضم الطرق الناتجة عن إفراز العقارات إلى الملك العام.$q$,$q$[{"ar": "طلب على النموذج رقم 17 م.م. يحدد رقم الطريق الخاص ومنطقته العقارية والعقارات المستفيدة وأسماء مالكيها"}, {"ar": "ما يثبت أن الطريق يخدم أكثر من ستة عقارات مبنية أو قيد البناء تعود لستة مالكين مختلفين"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب وتسجيله"}, {"ar": "إحالته إلى الإدارة الفنية ثم قرار المجلس البلدي بضم الطريق وفق النموذج المعتمد"}, {"ar": "استكمال معاملات الضم والتسجيل العقاري"}]$q$::jsonb,$q$المجلس البلدي / الإدارة الفنية$q$,null,null from municipal_service where slug=$q$t-148$q$ on conflict (service_id,version_no) do nothing;
