insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$ترخيص بإنشاء مؤسسة مصنفة من الفئة الأولى أو الثانية (غير صناعية)$q$,$q$الفئة: المعاملات ذات العلاقة بالصحة العامة. الأساس القانوني: المرسوم الاشتراعي 21/ل (1932) م.1 و7–10 و13 و20 و26؛ المرسوم 1119/1936 م.1.$q$,$q$[{"ar": "اسم المستدعي وكنيته ومحل إقامته (أو اسم الشركة)"}, {"ar": "المكان الذي ستقام فيه المؤسسة وحدوده"}, {"ar": "نوع الصناعة وعدد العمال والمحركات وقوتها وكيفية استعمالها والمواد والمنتجات (عند الاقتضاء)"}, {"ar": "مصوّر موجز بمقياس 100/1 على الأقل تبين الجهات المحيطة إلى مسافة لا تقل عن 250 م للصنف الأول و50 م للصنف الثاني (بحسب نص المرسوم)"}, {"ar": "مصوّر إجمالي بمقياس 200/1 على الأقل بالترتيبات الداخلية والغاية من البناء"}, {"ar": "كيفية تصريف المياه المبتذلة والنفايات"}, {"ar": "إفادة عقارية شاملة لكامل البناء أو للقسم المفرز"}, {"ar": "إفادة ارتفاق وتخطيط (بيان مسطح تخطيط وبيان عن المجاري والمناطق الارتفاقية)"}, {"ar": "عقد إيجار إذا كان صاحب العلاقة مستأجراً"}, {"ar": "بيان بالمحركات على ثلاث نسخ (الرقم المتسلسل، القوة، الماركة، جهة الاستعمال)"}, {"ar": "وصف للمشروع مع المطالعات الفنية والصحية"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب إلى المحافظ (أو القائمقام) مع المستندات"}, {"ar": "تحقيق: شهر واحد للصنف الأول (بإلصاق إعلانات) و15 يوماً للصنف الثاني"}, {"ar": "طلب رأي المجلس البلدي الذي يبديه خلال شهر واحد"}, {"ar": "لصاحب الصناعة مذكرة جوابية على التحقيق خلال 15 يوماً من تبلغه المحضر؛ يرسل المحقق الملف إلى المحافظ خلال 8 أيام من رد صاحب العلاقة"}, {"ar": "قرار اللجنة الصحية وتبليغه؛ وللمعني خلال 8 أيام بعد التبليغ أن يعترض"}, {"ar": "قرار الترخيص"}]$q$::jsonb,$q$المحافظ / القائمقام مع رأي المجلس البلدي واللجنة الصحية (يقدم الطلب في مركز المحافظة أو القائمقامية)$q$,null,$q$أربعة أشهر باستثناء المهلة التي تستغرقها المعاملة أمام اللجنة الصحية$q$ from municipal_service where slug=$q$t-149$q$ on conflict (service_id,version_no) do nothing;
