insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$وصل بالتصريح لمؤسسة مصنفة من الفئة الثالثة (غير صناعية)$q$,$q$الفئة: المعاملات ذات العلاقة بالصحة العامة. الأساس القانوني: المرسوم الاشتراعي 21/ل (1932)؛ المرسوم 1119/1936 م.1؛ المرسوم الاشتراعي 116/1959 م.26 و35.$q$,$q$[{"ar": "طلب موقع من صاحب العلاقة أو من ينوب عنه"}, {"ar": "إفادة عقارية لا يعود تاريخها لأكثر من ثلاثة أشهر"}, {"ar": "عقد إيجار إذا كان صاحب العلاقة مستأجراً"}, {"ar": "إفادة تخطيط وارتفاق (بيان مسطح تخطيط وبيان المجاري والمناطق الارتفاقية)"}, {"ar": "وصف للمشروع مع المطالعات الفنية والصحية"}, {"ar": "بيان بالمحركات على ثلاث نسخ"}, {"ar": "بطاقة هوية أو إخراج قيد، أو إجازة عمل لغير اللبنانيين مع صورة الهوية"}]$q$::jsonb,$q$[{"ar": "تقديم التصريح الخطي إلى القائمقام (المحافظ في القضاء المركزي)"}, {"ar": "إعطاء الوصل بالتصريح؛ ويرخص القائمقام بناءً على اقتراح طبيب القضاء بالرخص الصحية النافذة عدا المستشفيات والمستوصفات"}]$q$::jsonb,$q$القائمقام (المحافظ في القضاء المركزي)$q$,null,null from municipal_service where slug=$q$t-150$q$ on conflict (service_id,version_no) do nothing;
