insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$ترخيص بإنشاء واستثمار مؤسسة سياحية أو مكان اجتماع أو نادي مراهنات$q$,$q$الفئة: المعاملات ذات الصفة الاقتصادية. الأساس القانوني: المرسوم 15598/1970 م.1 و2؛ القرار 3210/1974؛ المرسوم الاشتراعي 21/ل (1932) م.13.$q$,$q$[{"ar": "طلب موقع من صاحب العلاقة أو من ينوب عنه قانوناً"}, {"ar": "الموافقة المبدئية (موافقة المرحلة الأولى) من وزارة السياحة"}, {"ar": "إخراج قيد يثبت أن صاحب الطلب لبناني أتم الحادية والعشرين، أو صورة عن جواز السفر لغير اللبناني"}, {"ar": "سجل عدلي يثبت حسن سيرة من يكلف بإدارة المؤسسة وعدم الحكم عليه بجناية أو جنحة شائنة"}, {"ar": "وثيقة تثبت مؤهلات المدير المهنية أو شهادات تخصص من المعاهد السياحية"}, {"ar": "وثيقة تسجيل المؤسسة في محكمة التجارة تنحصر بموضوع الترخيص"}, {"ar": "للشركات: ما يثبت كيانها القانوني في لبنان"}, {"ar": "رخصة أشغال مع الخرائط مصدقة من المرجع المختص أو ما يقوم مقامها"}, {"ar": "سند إيجار مسجل لدى البلدية أو سند تمليك"}, {"ar": "وثيقة باسم المؤسسة توافق عليه الوزارة"}, {"ar": "صور فوتوغرافية لجميع أقسام المؤسسة"}]$q$::jsonb,$q$[{"ar": "التقدم إلى وزارة السياحة بفكرة المشروع لنيل موافقة المرحلة الأولى"}, {"ar": "استكمال المستندات وتقديم الطلب"}, {"ar": "موافقة المجلس البلدي (م.49 بلديات) ثم قرار الترخيص"}]$q$::jsonb,$q$وزارة السياحة (يقدم الطلب لديها) مع موافقة المجلس البلدي$q$,null,$q$تحديد المهلة يعود إلى وزارة السياحة$q$ from municipal_service where slug=$q$t-152$q$ on conflict (service_id,version_no) do nothing;
