insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الوصول إلى المعلومات والمستندات الإدارية لدى البلدية (قانون 28/2017)$q$,$q$الفئة: معاملات عامة. الأساس القانوني: قانون الحق في الوصول إلى المعلومات 28/2017 (م.3 و10 و14–19)؛ م.45 قانون البلديات.$q$,$q$[{"ar": "طلب خطي يتضمن الاسم الثلاثي ومحل الإقامة المختار وتحديداً واضحاً ودقيقاً للمعلومة أو المستند والفترة الزمنية المطلوبة"}, {"ar": "إثبات الهوية للتحقق منها"}, {"ar": "وكالة خاصة إن قدم الطلب عن طريق ممثل"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب الخطي إلى موظف المعلومات المكلف في البلدية"}, {"ar": "طلب الموظف إيضاحات خطية مرة واحدة ضمن مهلة الرد (تتوقف المهلة إلى حين الجواب)"}, {"ar": "قرار الإدارة بالموافقة أو الرفض؛ والرفض يجب أن يكون خطياً ومعللاً ويبلغ لصاحب العلاقة"}, {"ar": "عند الموافقة: الاطلاع مجاناً في مكان وجود المستند، أو الحصول على صورة أو نسخة طبق الأصل على نفقة الطالب بحدود كلفة الاستنساخ"}, {"ar": "عند الرفض الصريح أو الضمني: المراجعة خلال شهرين أمام الهيئة الإدارية المستقلة (الهيئة الوطنية لمكافحة الفساد)؛ وفي غياب إنشائها يطعن أمام مجلس شورى الدولة بالإبطال لتجاوز حد السلطة"}]$q$::jsonb,$q$البلدية — موظف المعلومات المكلف$q$,null,$q$مهلة المراجعة بعد الرفض: شهران / عدم الرد ضمن مهلة الرد القانونية يعد رفضاً ضمنياً قابلاً للطعن$q$ from municipal_service where slug=$q$t-153$q$ on conflict (service_id,version_no) do nothing;
