insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الترخيص بموقف أو وقوف سيارات عمومية (أجرة / نقل مشترك) على الطريق البلدي العام$q$,$q$الفئة: الأملاك والأشغال العامة. الأساس القانوني: قانون البلديات م.49 بند 17 وم.74 بنود 11 و20؛ قانون الرسوم البلدية 60/1988 م.44 و48؛ قانون السير.$q$,$q$[{"ar": "طلب خطي من صاحب السيارة العمومية"}, {"ar": "رخصة السير وإجازة السوق من الفئة المناسبة للمركبة"}, {"ar": "إثبات المعاينة الميكانيكية السارية"}, {"ar": "إثبات استيفاء شروط مهنة النقل بالأجرة وفق قانون السير (م.122 وما يليها)"}]$q$::jsonb,$q$[{"ar": "تحديد المجلس البلدي أماكن الوقوف المخصصة (والنظام المالي بمصادقة وزير الداخلية)"}, {"ar": "تقديم الطلب إلى رئيس البلدية ودرسه في دائرة السير (حيث وجدت)"}, {"ar": "منح الترخيص بتعيين مكان وقوف محدد على الطريق وفق الأصول"}, {"ar": "مراقبة الالتزام بشروط الترخيص (معاينة ميكانيكية، فحوص طبية، تسديد الرسوم المتوجبة)"}]$q$::jsonb,$q$رئيس البلدية (والمحافظ في بيروت)$q$,null,$q$خارج النطاق البلدي: يعطي الترخيص القائمقام أو المحافظ$q$ from municipal_service where slug=$q$t-154$q$ on conflict (service_id,version_no) do nothing;
