insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الترخيص بإقامة حفلة أو نشاط على طريق عام أو حديقة بلدية$q$,$q$الفئة: الأملاك والأشغال العامة. الأساس القانوني: قانون البلديات م.74؛ قرارا وزارة التربية 386/1944 و44/1974 (الحفلات الرياضية).$q$,$q$[{"ar": "طلب خطي يحدد المكان والتاريخ والمدة وبرنامج النشاط"}, {"ar": "موافقة الجهة الرياضية المختصة (وزارة الشباب والرياضة) إن كان النشاط رياضياً"}, {"ar": "التعهد بمراعاة السير والأمن والنظافة"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب إلى رئيس البلدية"}, {"ar": "تقدير البلدية مدى ملاءمة المكان وحركة السير"}, {"ar": "منح الترخيص بتحديد المكان والمدة، وعند تعدد الطالبين توزع الأماكن بحسب الأولوية"}, {"ar": "للتظاهرة الرياضية على الطريق ترخيص خاص إضافي من الجهة الرياضية المختصة؛ وللأوتوسترادات قرار من وزير الداخلية"}]$q$::jsonb,$q$رئيس البلدية (والجهة الرياضية المختصة للتظاهرات الرياضية)$q$,null,null from municipal_service where slug=$q$t-155$q$ on conflict (service_id,version_no) do nothing;
