insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب تركيب ألواح الطاقة الشمسية (أقل من 1.5 ميغاواط)$q$,$q$الفئة: البناء والتنظيم. الأساس القانوني: القرار المشترك لوزراء الداخلية والأشغال والطاقة تاريخ 9/9/2026.$q$,$q$[{"ar": "استمارة الطلب"}, {"ar": "إفادتا تحمل مسؤولية موقعتان من مهندس إنشائي ومهندس كهربائي أو كهروميكانيكي مسجلين في نقابة المهندسين"}, {"ar": "إفادة ارتفاق وتخطيط"}, {"ar": "النموذج المعتمد من نقابة المهندسين الذي يثبت توافر المواصفات"}, {"ar": "للمستأجر أو الشاغل: موافقة مالك القسم"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب من المالك أو الشاغل القانوني أو وكيله إلى البلدية أو القائمقام"}, {"ar": "للبلدية طلب استكمال النواقص؛ ولا يقبل الطلب للعقار المتوقفة أعماله بسبب مخالفة ما لم تزل أو تسو"}, {"ar": "البت في الطلب والموافقة عليه (دور البلدية: التحقق من الشروط الإدارية والعمرانية والهندسية والسلامة العامة)"}, {"ar": "تصديق نقابة المهندسين تواقيع المهندسين على المخططات والاتفاقيات المرفقة (دون صلاحية الموافقة)"}, {"ar": "تسديد الرسم المقطوع وفق قانون الرسوم والعلاوات البلدية ثم التركيب بإشراف المهندسين"}, {"ar": "بعد الإنجاز: إفادة نهائية من المهندسين بصلاحية النظام ومطابقته لشروط السلامة"}, {"ar": "حفظ نسخة في أرشيف البلدية وتسليم نسخة لصاحب العلاقة وإرسال نسخة إلى وزارة الطاقة والمياه"}]$q$::jsonb,$q$البلدية (والقائمقام حيث لا بلدية)$q$,null,$q$تبت البلدية أو القائمقام في الطلب خلال 15 يوماً من تسجيله أو استكمال مستنداته؛ وعند عدم البت يعتبر مقبولاً حكماً ويحق المباشرة بعد تسديد الرسوم / إنجاز التركيب خلال سنة من تبلغ الموافقة وإلا اعتبرت لاغية وتطلب موافقة جديدة$q$ from municipal_service where slug=$q$t-156$q$ on conflict (service_id,version_no) do nothing;
