insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الاستحصال على إذن مسبق بطباعة الخاتم الاختياري (للمختار المنتخب)$q$,$q$الفئة: معاملات المختارين. الأساس القانوني: المادة 17 من قانون المختارين والمجالس الاختيارية (الخاتم وفق نموذج تضعه وزارة الداخلية والبلديات)؛ تعاميم وزير الداخلية والبلديات (2025: رقم 6671 و2351 و2606).$q$,$q$[{"ar": "طلب إذن بطباعة الخاتم الاختياري وفق النموذج الجديد المعتمد (منشور على موقع المديرية) وبحسب مقاسات النموذج المرفق بالتعميم"}, {"ar": "نسخة عن نتيجة الانتخاب موقّعة وفق الأصول (أو ورود الاسم على لائحة الناجحين المبلّغة)"}, {"ar": "محضر حلف اليمين (عند التقديم لدى القائمقامية)"}, {"ar": "صورة عن بطاقة الهوية أو إخراج قيد إفرادي"}, {"ar": "إيصال يبيّن تقديم التصريح عن الذمة المالية عملاً بالقانون الناظم للتصريح عن الذمة المالية والإثراء غير المشروع (رقمه غير مقروء بدقة في الإعلان الممسوح)"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب بالنموذج الجديد مع المستندات إلى المديرية العامة للإدارات والمجالس المحلية، أو (بحسب التعميم رقم 2606/2025) إلى القائمقام في القضاء تسهيلاً على المختارين"}, {"ar": "تدقيق ورود الاسم على لائحة الناجحين وصحة المستندات"}, {"ar": "إصدار موافقة/إذن مسبق بطباعة الخاتم"}, {"ar": "طباعة الخاتم وفق النموذج والمقاسات المعتمدة"}, {"ar": "توثيق الخاتم والتوقيع (انظر A2-002) ثم مباشرة إصدار الإفادات"}]$q$::jsonb,$q$المديرية العامة للإدارات والمجالس المحلية - وزارة الداخلية والبلديات (يُقدَّم الطلب مباشرة أو عبر القائمقامية/المحافظة)$q$,null,$q$إلزامي قبل الطباعة: لا يُوثَّق أي ختم صدر قبل الحصول على الموافقة (تعميم 2351 تاريخ 2025/05/28)$q$ from municipal_service where slug=$q$t-183$q$ on conflict (service_id,version_no) do nothing;
