insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$توثيق الخاتم الاختياري وتوقيع المختار لدى القائمقامية/المحافظة$q$,$q$الفئة: معاملات المختارين. الأساس القانوني: المادة 17 من قانون المختارين والمجالس الاختيارية؛ تعاميم 2606/2025 و2351/2025.$q$,$q$[{"ar": "الخاتم المطبوع وفق النموذج المعتمد بعد الحصول على الإذن"}, {"ar": "نموذج توقيع المختار"}, {"ar": "بطاقة الهوية"}]$q$::jsonb,$q$[{"ar": "حضور المختار إلى القائمقامية (أو المحافظة) المختصة بدل المديرية العامة"}, {"ar": "تسجيل نموذج الخاتم والتوقيع في سجل التوثيق وإيداع نسخة"}, {"ar": "إبلاغ المديرية/المحافظات بنسخة عن مستند التوثيق عند الحاجة"}]$q$::jsonb,$q$المديرية العامة للإدارات والمجالس المحلية - وزارة الداخلية والبلديات / القائمقامية أو المحافظة المختصة$q$,null,null from municipal_service where slug=$q$t-184$q$ on conflict (service_id,version_no) do nothing;
