insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إفادة علم وخبر لعقار غير ممسوح (تنظيمها أو تجديدها) — المختار$q$,$q$الفئة: معاملات المختارين. الأساس القانوني: مادة (رقمها غير مقروء بدقة) من المرسوم الاشتراعي رقم 17 تاريخ 14 شباط 1971 (تنظيم مكاتب الطابو ومكاتب التسجيل)؛ مادتان من قانون المختارين والمجالس الاختيارية (1947)؛ استشارة مجلس شورى الدولة؛ تعميم الوزير رقم 5 تاريخ 2026/11/03 (يلغي كل التعاميم السابقة ذات الصلة) وتعميم 2012/2.$q$,$q$[{"ar": "طلب الحصول على إفادة علم وخبر لدى مختار القرية"}, {"ar": "المستندات الرسمية المثبتة للحقوق على العقار"}, {"ar": "خرائط إظهار الحدود المصدّقة وفق الأصول"}]$q$::jsonb,$q$[{"ar": "يقدّم صاحب العلاقة الطلب إلى مختار القرية مرفقاً بالمستندات الرسمية المثبتة للحقوق وخرائط الحدود"}, {"ar": "يرفع المختار كامل الملف إلى القائمقام أو المحافظ (مركز المحافظة)"}, {"ar": "يحيل القائمقام/المحافظ الملف إلى القطعة الإقليمية المختصة لدى قوى الأمن الداخلي للتحقيق في المعلومات والوقائع والتواقيع وسماع الإفادات"}, {"ar": "عند عدم وجود مانع قانوني يُعاد الملف إلى المختار عبر القائمقام/المحافظ لتنظيم الإفادة وتوقيعها مقترنة بتوقيع عضو المجلس الاختياري (أو أحد مختاري البلدة، أو أحد مختاري الأحياء)"}, {"ar": "عند وجود مانع قانوني يُعاد الملف مع نسخة عن التحقيق إلى صاحب العلاقة"}, {"ar": "يودع المختار نسخة عن كل إفادة منظمة لدى القائمقام/المحافظ"}]$q$::jsonb,$q$المختار + الاختياري المشارك + القائمقام/المحافظ + القطعة الإقليمية لقوى الأمن الداخلي$q$,null,null from municipal_service where slug=$q$t-185$q$ on conflict (service_id,version_no) do nothing;
