insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$التصريح عن الذمة المالية والمصالح لأعضاء المجالس البلدية والاختيارية والمختارين$q$,$q$الفئة: التزامات أعضاء المجالس المحلية. الأساس القانوني: القانون الناظم للتصريح عن الذمة المالية والإثراء غير المشروع (رقمه غير مقروء بدقة في التعاميم الممسوحة)؛ تعاميم الوزير 4199 و2457 و7004 (2025) وتعميم بدون رقم تاريخ 2025/01/04.$q$,$q$[{"ar": "تصريح الذمة المالية وفق نموذج الهيئة"}, {"ar": "إيصال تقديم التصريح (مطلوب لإذن طباعة الخاتم الاختياري)"}]$q$::jsonb,$q$[{"ar": "تنظيم الجداول بأسماء أعضاء المجالس البلدية والمختارين المنتخبين والمنتهية ولايتهم ومراجعهم وإيداعها الهيئة"}, {"ar": "تعميم الأعضاء بوجوب تقديم التصريح خلال المهلة القانونية"}, {"ar": "تقديم التصريح إلى الهيئة والحصول على إيصال"}, {"ar": "إبراز الإيصال عند طلب إذن طباعة الخاتم (للمختار)"}]$q$::jsonb,$q$الهيئة الوطنية لمكافحة الفساد (إيداع التصريح) — وتبلّغ الوزارة/المحافظات/القائمقامات الأعضاء$q$,null,$q$مهلة التقديم محددة في القانون والتعميم (تقرأ من نص التعميم المرجعي — لم تُستخرج بدقة)$q$ from municipal_service where slug=$q$t-198$q$ on conflict (service_id,version_no) do nothing;
