insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الإعفاء من الرسم المالي على الطلبات والعرائض والإفادات المقدمة من المواطنين إلى البلديات والإدارات$q$,$q$الفئة: معاملات عامة. الأساس القانوني: إعلام وزارة المالية (2025) بالاستناد إلى مادة من قانون الموازنة العامة 2025؛ تعميم رئاسة مجلس الوزراء رقم 18/2025؛ تعميما الوزير 2342/2025 و8163/2025.$q$,$q$[{"ar": "الطلب أو العريضة أو الاستدعاء أو الإفادة المقدمة من المواطن"}, {"ar": "ما يثبت الصفة (مواطن مقدِّم الطلب)"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب/العريضة/الاستدعاء إلى البلدية أو الاتحاد أو الإدارة العامة"}, {"ar": "قبول الطلب دون استيفاء رسم مالي على الطلب نفسه بحسب أصول الإعفاء الواردة في تعميم وزارة المالية"}, {"ar": "يُستثنى ما حدده التعميم المالي من معاملات (يراجع النص الأصلي)"}]$q$::jsonb,$q$الجهة العامة المقدَّم إليها الطلب (بلدية/اتحاد/إدارة عامة)$q$,null,null from municipal_service where slug=$q$t-199$q$ on conflict (service_id,version_no) do nothing;
