insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الإفادة عن المباني البلدية/الاتحادية/الاختيارية المتضررة وتقييم الاحتياجات (بعد الاعتداءات)$q$,$q$الفئة: معاملات بين البلدية والوزارة. الأساس القانوني: تعاميم الوزير 321/2025 و3594/2025 و9697/2024.$q$,$q$[{"ar": "لوائح/استمارات الأضرار المطلوبة بموجب التعميم"}, {"ar": "صور وتقارير فنية عند الاقتضاء"}]$q$::jsonb,$q$[{"ar": "تنظيم الاستمارة المطلوبة"}, {"ar": "رفعها بالتسلسل الإداري أو مباشرة إلى المديرية"}, {"ar": "متابعة تأمين الاعتمادات"}]$q$::jsonb,$q$المديرية العامة للإدارات والمجالس المحلية - وزارة الداخلية والبلديات$q$,null,null from municipal_service where slug=$q$t-200$q$ on conflict (service_id,version_no) do nothing;
