insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$تصديق قرار المجلس البلدي من سلطة الرقابة (القائمقام / المحافظ / وزير الداخلية)$q$,$q$الفئة: الرقابة الإدارية على البلديات. الأساس القانوني: قانون البلديات (م.54 قاعدة النفاذ الذاتي، م.60 تصديق القائمقام، م.61 تصديق المحافظ، م.62 تصديق وزير الداخلية، م.63 التصديق الضمني).$q$,$q$[{"ar": "قرار المجلس البلدي المطلوب تصديقه (نسخة طبق الأصل مع محضر الجلسة)"}, {"ar": "المستندات الفنية والمالية المرفقة بالقرار (دفتر شروط، تخمين، خرائط، موازنة…) بحسب نوعه"}, {"ar": "كتاب إيداع من رئيس البلدية إلى الوحدة المختصة لدى سلطة الرقابة"}]$q$::jsonb,$q$[{"ar": "اتخاذ القرار في المجلس البلدي (المرحلة التقريرية)"}, {"ar": "إيداعه لدى الوحدة المختصة لدى القائمقام/المحافظ/الوزارة وتسجيله"}, {"ar": "فحص المشروعية وملاءمة المصلحة العامة وصدور قرار خطي بالموافقة أو الرفض (لا تعديل ولا موافقة مشروطة)"}, {"ar": "التصديق الصريح: القرار نافذ منذ تاريخ التصديق ويرتد أثره إلى تاريخ صدوره"}, {"ar": "عند السكوت: التصديق الضمني بعد انقضاء المهلة بشرط إعلام رئيس البلدية سلطة الرقابة بأن القرار أصبح مصدقاً"}, {"ar": "نشر القرار النظامي على لوح إعلانات مركز البلدية وتبليغ القرار الفردي"}]$q$::jsonb,$q$القائمقام أو المحافظ أو وزير الداخلية والبلديات بحسب موضوع القرار (وفي بلدية بيروت: وزير الداخلية وحده)$q$,null,$q$مهلة بت القائمقام/المحافظ/الوزير في القرارات الخاضعة للتصديق (م.60–62): شهر من تاريخ تسجيل القرار لدى الوحدة المختصة، وبعدها يُعد مصدقاً ضمناً بشرط إعلام سلطة الرقابة / المهلة لا تُطبق على قرارات التخطيط والموازنة وفتح ونقل الاعتمادات والقروض (م.63 الفقرة الأخيرة): لا تصديق ضمني فيها / في الكتاب عبارة أخرى (ثلاثون يوماً بعد الإيداع) عند الحديث عن تصديق القائمقام/المحافظ — يُراجع نص م.63 الأصلي$q$ from municipal_service where slug=$q$t-201$q$ on conflict (service_id,version_no) do nothing;
