insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$المراجعة التسلسلية لدى وزير الداخلية عند رفض القائمقام أو المحافظ التصديق$q$,$q$الفئة: الرقابة الإدارية على البلديات. الأساس القانوني: قانون البلديات م.60–62 والمراجعة التسلسلية؛ نظام مجلس شورى الدولة.$q$,$q$[{"ar": "كتاب مراجعة تسلسلية من رئيس البلدية أو صاحب مصلحة"}, {"ar": "صورة عن قرار المجلس البلدي وعن قرار الرفض"}, {"ar": "أسباب الاعتراض ومستنداتها"}]$q$::jsonb,$q$[{"ar": "صدور رفض التصديق من القائمقام أو المحافظ"}, {"ar": "تقديم مراجعة تسلسلية إلى وزير الداخلية (من البلدية أو من كل ذي مصلحة)"}, {"ar": "بت الوزير"}, {"ar": "عند الرفض: الطعن بقرار الرفض أمام مجلس شورى الدولة (B-004) أو إعادة إصدار القرار متجنباً سبب الرفض"}]$q$::jsonb,$q$وزير الداخلية والبلديات$q$,null,$q$لم يرد في الكتاب أجل محدد للمراجعة التسلسلية؛ يُراجع الأجل العام للطعن بالقرار الإداري (شهران) لمن يطعن قضائياً$q$ from municipal_service where slug=$q$t-202$q$ on conflict (service_id,version_no) do nothing;
