insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إرجاء تنفيذ قرار المجلس البلدي لأسباب أمنية (م.65) والطعن به$q$,$q$الفئة: الرقابة الإدارية على البلديات. الأساس القانوني: قانون البلديات م.65 (سلطة الإرجاء).$q$,$q$[{"ar": "قرار معلَّل بالإرجاء يحدد مدته (يصدر عن سلطة الرقابة)"}, {"ar": "لائحة طعن أمام مجلس شورى الدولة (للبلدية أو صاحب مصلحة)"}]$q$::jsonb,$q$[{"ar": "صدور قرار الإرجاء المعلَّل لأسباب أمنية تتعلق بتنفيذ قرار المجلس (لا قرارات رئيس البلدية)"}, {"ar": "وقف التنفيذ مؤقتاً مع جواز استكمال الإجراءات غير التنفيذية"}, {"ar": "انتهاء مدة الإرجاء أو الطعن بالقرار أمام مجلس الشورى"}]$q$::jsonb,$q$القائمقام أو المحافظ أو وزير الداخلية$q$,null,$q$مدة الإرجاء تُحددها سلطة الرقابة في قرارها؛ القانون لم يضع حداً أقصى (انتقده الكتاب)$q$ from municipal_service where slug=$q$t-203$q$ on conflict (service_id,version_no) do nothing;
