insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الطعن أمام مجلس شورى الدولة بقرار سلطة الرقابة (تصديق أو رفض) أو بقرار المجلس البلدي$q$,$q$الفئة: القضاء الإداري. الأساس القانوني: نظام مجلس شورى الدولة م.60–70 والمادتان 105 و106 (شروط قبول إبطال تجاوز حد السلطة، المصلحة والصفة)؛ قانون 227/2000.$q$,$q$[{"ar": "لائحة مراجعة إبطال لتجاوز حد السلطة موقعة من محام"}, {"ar": "صورة عن القرار المطعون فيه (ونشره أو إثبات التبليغ)"}, {"ar": "ما يثبت الصفة والمصلحة الشخصية المباشرة"}]$q$::jsonb,$q$[{"ar": "التأكد من أن القرار إداري نافذ ومنتج للضرر (القرار قبل التصديق لا يُطعن به)"}, {"ar": "تقديم المراجعة ضمن المهلة"}, {"ar": "تبادل اللوائح والتحقيق"}, {"ar": "الحكم بالإبطال أو الرد"}]$q$::jsonb,$q$مجلس شورى الدولة$q$,null,$q$مهلة الطعن: شهران من نشر القرار (التنظيمي) أو من التبليغ (الفردي) — م.69 من نظام المجلس / تبدأ مهلة الطعن بالقرار البلدي المصدق من تاريخ التصديق / الطعن بقرار إسقاط ملك عام: من نشر مرسوم الإسقاط في الجريدة الرسمية دون تبليغ فردي (اجتهاد)$q$ from municipal_service where slug=$q$t-204$q$ on conflict (service_id,version_no) do nothing;
