insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إسقاط ملك بلدي عام (طريق أو فضلة أو عقار) إلى الملك البلدي الخاص$q$,$q$الفئة: الأملاك البلدية العامة. الأساس القانوني: قانون البلديات م.49 ف.16 و62 ف.7؛ القرار 144/1925 م.24؛ المرسوم 1315/1965 (تصنيف الطرق).$q$,$q$[{"ar": "قرار المجلس البلدي بالإسقاط مع بيان زوال التخصيص للمنفعة العامة"}, {"ar": "خريطة المنطقة وبيان الاستعمال"}, {"ar": "اقتراح الجهة المختصة بالتحديد (التنظيم المدني عند الطرق)"}, {"ar": "ما يثبت أن العقار فضلة لا تخدم المنفعة العامة"}]$q$::jsonb,$q$[{"ar": "قرار المجلس البلدي بالإسقاط"}, {"ar": "تصديق وزير الداخلية والبلديات"}, {"ar": "نشر المرسوم/القرار حيث يوجب القانون"}, {"ar": "تسجيل العقار كملك خاص للبلدية"}, {"ar": "بيع الفضلة أو التصرف بها وفق الأصول"}]$q$::jsonb,$q$المجلس البلدي (القرار)؛ وزير الداخلية والبلديات (التصديق، م.49 ف.16)؛ مجلس الوزراء (خارج النطاق البلدي)$q$,null,$q$مهلة الطعن بقرار الإسقاط: شهران من النشر في الجريدة الرسمية$q$ from municipal_service where slug=$q$t-213$q$ on conflict (service_id,version_no) do nothing;
