insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$تحديد الأملاك العمومية البلدية (التحديد الإداري بلجنة) والاعتراض عليه$q$,$q$الفئة: الأملاك البلدية العامة. الأساس القانوني: القرار 144/1925 (المواد 7–13 و21–24)؛ القرارات 186 و188 و189/1926.$q$,$q$[{"ar": "قرار بالأمر بإجراء التحديد يحدد المنطقة ونوع الأملاك"}, {"ar": "محضر التحديد والرسم المرافق"}, {"ar": "سجل التحقيق (الاعتراضات)"}, {"ar": "تصريح خطي بقبول أصحاب الشواطئ عند الاقتضاء"}]$q$::jsonb,$q$[{"ar": "صدور الأمر بالتحديد"}, {"ar": "تحديد مؤقت بحضور اللجنة وتبليغ المحضر بالتلصيق والنشر"}, {"ar": "وضع المحضر والرسم لدى رئيس المنطقة لتلقي الاعتراضات"}, {"ar": "النظر بالاعتراضات وتعديل التحديد"}, {"ar": "توقيع المحاضر وإرسالها لتثبيت الحدود بقرار"}, {"ar": "القيد في السجل العقاري"}]$q$::jsonb,$q$لجنة التحديد (رئيس: مهندس النافعة، عضو من المالية، عضو من البلدية)؛ رئيس الدولة/المرجع بقرار التثبيت؛ القاضي العقاري$q$,null,$q$مدة وضع المحضر والرسم في مكتب رئيس المنطقة: شهر / مهلة الطعن بحقوق الدولة والبلديات المذكورة في خرائط المساحة: سنتان من إيداع الخرائط (م.18 من القرار 188) وهي مهلة إسقاط / لا يُطعن بمرسوم تصديق التحديد بالإبطال بعد سنتين من الإيداع ولا بالقضاء الشامل بعد عشر سنوات تلي مهلة السنتين (اجتهاد)$q$ from municipal_service where slug=$q$t-214$q$ on conflict (service_id,version_no) do nothing;
