insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إزالة التعدي الإداري على الملك البلدي العام: إنذار وغرامة إدارية والاعتراض عليها$q$,$q$الفئة: الأملاك البلدية العامة. الأساس القانوني: القرار 144/1925 م.21–24 المعدلة بالمرسوم الاشتراعي 15403/1964.$q$,$q$[{"ar": "محضر ضبط المخالفة"}, {"ar": "إنذار إلى الشاغل"}, {"ar": "قرار فرض الغرامة"}, {"ar": "اعتراض خطي مرفق بإيصال دفع الغرامة"}]$q$::jsonb,$q$[{"ar": "ضبط المخالفة بمحضر"}, {"ar": "إنذار المعتدي بالإزالة أو بالخضوع لشروط الإشغال"}, {"ar": "فرض غرامة إدارية"}, {"ar": "اعتراض المخالف أمام محكمة المنطقة مع إيصال الدفع"}, {"ar": "عند التكرار: سجن 10 أيام إلى ثلاثة أشهر أمام المحكمة الجزائية"}, {"ar": "هدم الأشغال غير المشروعة على نفقة المخالف"}]$q$::jsonb,$q$رئيس البلدية (الإنذار)؛ السلطة الإدارية المحددة بمرسوم لفرض الغرامة؛ محكمة المنطقة (الاعتراض)$q$,null,$q$مهلة الاعتراض: 15 يوماً من تبلُّغ القرار الإداري بفرض الغرامة، ويُبلَّغ الاعتراض خلالها للسلطة التي فرضتها / القرار الإداري يصبح مبرماً إن لم يقدَّم الاعتراض$q$ from municipal_service where slug=$q$t-216$q$ on conflict (service_id,version_no) do nothing;
