insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إدارة الأراضي المشاعية: قرارات اللجنة المشاعية وموازنتها وتجزئة الأراضي$q$,$q$الفئة: الأملاك المشاعية. الأساس القانوني: المرسوم 1576/1950؛ قرار 171/1926 و37/ل.ر. (تجزئة المشاعات)؛ قانون الغابات م.57 و61.$q$,$q$[{"ar": "قرار اللجنة المشاعية في ثلاث نسخ"}, {"ar": "مشروع موازنة الواردات والنفقات"}, {"ar": "طلب ترخيص مصلحة الغابات لاستثمار الغابات"}]$q$::jsonb,$q$[{"ar": "اجتماع اللجنة بدعوة خطية وبغالبية الأصوات"}, {"ar": "إرسال القرار إلى المحافظ بواسطة القائمقام لإحالته إلى وزير الزراعة"}, {"ar": "تصديق الوزير فتنفذ القرارات"}, {"ar": "وضع الموازنة وإرسالها وتصديقها"}, {"ar": "بيان الصرف آخر كانون الأول"}]$q$::jsonb,$q$اللجنة المشاعية؛ المجلس البلدي (حيث توجد بلدية)؛ المحافظ؛ وزير الزراعة (التصديق)$q$,null,$q$إرسال صورة القرار خلال ثمانية أيام / موازنة السنة المقبلة تُرسل خلال تشرين الثاني / بيان الأموال آخر كانون الأول$q$ from municipal_service where slug=$q$t-221$q$ on conflict (service_id,version_no) do nothing;
