insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$حجز وبيع بالمزاد لتحصيل الرسوم البلدية وتملك البلدية العقار المباع$q$,$q$الفئة: الجباية والتحصيل. الأساس القانوني: قانون أصول المحاكمات المدنية م.900–989؛ قانون الرسوم والعلاوات البلدية.$q$,$q$[{"ar": "إنذار عام أو شخصي"}, {"ar": "محضر الحجز"}, {"ar": "دفتر شروط البيع"}]$q$::jsonb,$q$[{"ar": "نشر إنذار بالدفع"}, {"ar": "تبليغ المكلف"}, {"ar": "حجز الأموال"}, {"ar": "إبلاغ الدائرة العقارية بإشارة الحجز"}, {"ar": "بيع بالمزاد العلني"}, {"ar": "تملك البلدية العقار عند عدم وجود مزايد"}]$q$::jsonb,$q$المحتسب المختص؛ لجنة البيع؛ القائمقام أو المحافظ (تصديق دفتر الشروط للعقار)$q$,null,$q$الإنذار يُنشر مرتين خلال عشرة أيام ويُدعى المتخلفون للدفع خلال 15 يوماً من أول نشر / مهلة 15 يوماً من تبلُّغ الإنذار الشخصي / إعلان بيع المنقول خلال أسبوعين من الحجز$q$ from municipal_service where slug=$q$t-222$q$ on conflict (service_id,version_no) do nothing;
