insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$استرداد عقار مستملَك بعد عدول الإدارة عن الاستملاك (صريح أو ضمني)$q$,$q$الفئة: الاستملاك والعقارات. الأساس القانوني: قانون الاستملاك 58/1991 (م.32 العدول قبل إيداع التعويض، م.33 الاسترداد، م.29 و31 إيداع التعويض ووضع اليد).$q$,$q$[{"ar": "طلب خطي من المالك أو خلفائه العموميين إلى الإدارة المستملِكة"}, {"ar": "سند ملكية وصحيفة عقارية حديثة للعقار"}, {"ar": "كتاب الإدارة المبلِّغ بالعدول (في حالة العدول الصريح)"}, {"ar": "ما يثبت عدم المباشرة الفعلية بتنفيذ المشروع خلال عشر سنوات (في حالة العدول الضمني)"}]$q$::jsonb,$q$[{"ar": "العدول الصريح: قرار صريح بموازاة الصيغ يُبلَّغ إلى المالك، ويكون ممكناً فقط قبل إيداع التعويض المقرر"}, {"ar": "العدول الضمني: انقضاء عشر سنوات من قرار وضع اليد دون مباشرة تنفيذ المشروع جزئياً أو كلياً ودون تخصيص العقار لمشروع آخر أُعلنت منفعته العامة"}, {"ar": "تقديم المالك طلب الاسترداد الخطي إلى الإدارة"}, {"ar": "إعادة تسجيل العقار باسم المالك في السجل العقاري"}]$q$::jsonb,$q$الإدارة أو البلدية المستملِكة؛ مالك العقار أو خلفاؤه العموميون يطلبون الاسترداد؛ السجل العقاري لتسجيل الاسترداد$q$,null,$q$العدول الصريح: لمالك العقار أو خلفائه العموميين طلب الاسترداد خلال سنة من تاريخ إبلاغهم العدول بالطريقة الإدارية / العدول الضمني: مدة عشر سنوات من تاريخ قرار وضع اليد، ثم سنة لتقديم طلب الاسترداد تبدأ من انقضاء العشر سنوات (مهلة إسقاط لا يسري عليها وقف مرور الزمن أو قطعه) / العدول الصريح لا يجوز إلا قبل إيداع التعويض كاملاً؛ الإيداع الجزئي لا يجيز وضع اليد$q$ from municipal_service where slug=$q$t-223$q$ on conflict (service_id,version_no) do nothing;
