insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الاستملاك الكامل للعقار المصاب جزئياً بالتخطيط عند عدم صلاحية الجزء المتبقي$q$,$q$الفئة: الاستملاك والعقارات. الأساس القانوني: قانون الاستملاك 58/1991 (م.27 طلب الاستملاك الكامل، م.28 بت اللجنة، م.31 نقل الملكية حكماً).$q$,$q$[{"ar": "استدعاء خطي يقدمه جميع مالكي العقار أو القسم المفرز إلى لجنة الاستملاك البدائية"}, {"ar": "سندات الملكية وشهادات القيد (تُسلَّم لنقل الفضلة إلى الإدارة)"}, {"ar": "ما يثبت أن الجزء المتبقي غير صالح للغاية المعد لها (كشف أو تقرير فني)"}]$q$::jsonb,$q$[{"ar": "تقديم الاستدعاء إلى لجنة الاستملاك البدائية"}, {"ar": "بت اللجنة بطلب الاستملاك الكامل وتحديد التعويض لسائر أصحاب الحقوق"}, {"ar": "تنظيم الإدارة المستملِكة بياناً بالعقارات المستملكة بكاملها وإبلاغه إلى الدوائر العقارية"}, {"ar": "إيداع التعويض ووضع اليد ثم نقل ملكية الفضلة حكماً إلى ملك الإدارة الخاص"}]$q$::jsonb,$q$لجنة الاستملاك البدائية المختصة؛ الإدارة المستملِكة؛ أمين السجل العقاري لنقل ملكية الفضلة$q$,null,$q$يسقط الحق في طلب الاستملاك الكامل بعد سنة من تاريخ القرار النهائي في الاستملاك الجزئي / التعويض يُقدَّر بالأسعار الرائجة بتاريخ قرار اللجنة البدائية العائد للاستملاك الجزئي$q$ from municipal_service where slug=$q$t-224$q$ on conflict (service_id,version_no) do nothing;
