insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب المالكين المجاورين استملاك المساحة المتبقية غير الصالحة للبناء من العقار المصاب بالتخطيط$q$,$q$الفئة: التنظيم المدني والاستملاك. الأساس القانوني: قانون التنظيم المدني (م.18 و19)؛ قانون الاستملاك (م.2 الأخيرة).$q$,$q$[{"ar": "طلب خطي من المالك المجاور لجهة واجهة عقاره"}, {"ar": "ما يثبت قيمة المساحة التقديرية (تأمين القيمة التقديرية بناءً على طلب الإدارة)"}, {"ar": "كفالة مصرفية تغطي ما قد يُحكم به على الإدارة نتيجة الاستملاك"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب إلى الإدارة أو البلدية المعنية"}, {"ar": "استملاك المساحات المتبقية غير الصالحة للبناء بموجب مرسوم لمصلحة المالك المجاور"}, {"ar": "تأمين المالك القيمة التقديرية والكفالة المصرفية"}, {"ar": "تحل الإدارة أو البلدية محل المالك المجاور الذي يمتنع عن الشراء"}]$q$::jsonb,$q$البلدية أو الإدارة المعنية؛ مرسوم استملاك؛ المالك المجاور صاحب الواجهة$q$,null,$q$لم يرد في المصدر مهلة محددة لهذا الطلب$q$ from municipal_service where slug=$q$t-225$q$ on conflict (service_id,version_no) do nothing;
