insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إلزام مالكي العقارات بتصوين الأرض وترميم الواجهات ودهانها (الإنذار والتنفيذ على نفقتهم)$q$,$q$الفئة: النظافة العامة والمظهر العمراني. الأساس القانوني: قانون النظافة العامة (المرسوم 8735 تاريخ 1974/8/23، م.9 و11 و20)؛ قانون البناء (م.18 فقرات 5–7)؛ قانون البلديات م.74 ف.13 (الأبنية المتداعية).$q$,$q$[{"ar": "قرار أو كتاب إنذار من البلدية إلى المالك"}, {"ar": "الإعلان في صحيفتين يومتين عند تعذر التبليغ المباشر"}]$q$::jsonb,$q$[{"ar": "تحديد المناطق المشمولة (قرى الاصطياف والاشتاء ومراكز المحافظات وما يقتضيه الغرض السياحي والنظافة)"}, {"ar": "توجيه الإنذار إلى المالك بالتصوين أو بالترميم والدهان"}, {"ar": "انقضاء مهلة الإنذار دون تنفيذ"}, {"ar": "تنفيذ البلدية الأعمال بالطرق الإدارية على نفقة المالك وتحصيل الكلفة بطريقة الضرائب المباشرة"}]$q$::jsonb,$q$البلدية (رئيس المجلس البلدي)$q$,null,$q$مهلة الإنذار: أسبوعان (م.20)، تبلَّغ مباشرة أو بالإعلان في صحيفتين يوميتين / ترميم وغسل ودهان الواجهات المطلة على الطرق الدولية والرئيسية: مرة كل خمس سنوات على الأكثر (م.11)$q$ from municipal_service where slug=$q$t-226$q$ on conflict (service_id,version_no) do nothing;
