insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$عملية التحسينات العقارية وضم القطع في الأراضي الزراعية$q$,$q$الفئة: الأراضي والمساحة. الأساس القانوني: القرار رقم 37/ل.ر. تاريخ 1934/2/5 (التحسينات العقارية في الأراضي الزراعية)؛ قانون التنظيم المدني (المرسوم الاشتراعي 69/1983).$q$,$q$[{"ar": "طلب أكثرية الملاكين أو مالكين تمثل أملاكهم نصف مساحة المنطقة الزراعية على الأقل (عند البدء بطلب الأهالي)"}, {"ar": "سندات الملكية والخرائط المساحية"}, {"ar": "محضر ضم لكل عقار جديد يوقعه المالك ذو العلاقة والمالكون المجاورون ويصادق عليه القاضي"}]$q$::jsonb,$q$[{"ar": "افتتاح العملية منطقة منطقة بقرار من القاضي العقاري"}, {"ar": "تخمين العقارات بحالتها الحاضرة ثم الضم والفرز الجديد"}, {"ar": "تخمين قيمة القطع الجديدة مع مراعاة التحسين الحاصل وتوزيعها على المالكين (مبادلة عيناً بعين)"}, {"ar": "إنشاء شبكة الطرق والمسالك وأقنية الري بمشاركة الملاكين بالعمل والأدوات"}, {"ar": "تعيين الحدود على الأرض ووضع التخوم وتنظيم محضر الضم"}, {"ar": "تسليم الأملاك وإعطاء شهادات مؤقتة بلا رسوم أو مصاريف ثم استبدالها بسندات الملكية"}]$q$::jsonb,$q$الإدارة المختصة (وزارة الأشغال العامة والنقل / المديرية العامة للتنظيم المدني)؛ القاضي العقاري؛ لجنة الضم؛ البلدية للاطلاع على الأراضي المشاعية$q$,null,$q$من افتتاح العملية حتى ختامها توقف المعاملات العقارية والحقوق العينية الخاصة بالأملاك المشمولة$q$ from municipal_service where slug=$q$t-227$q$ on conflict (service_id,version_no) do nothing;
