insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$مذكرة ربط النزاع مع البلدية قبل مراجعة القضاء الشامل (دعوى تعويض أو مطالبة)$q$,$q$الفئة: اعتراضات وطعون. الأساس القانوني: م.إ. 118/1977 المادتان 100 و101؛ نظام مجلس شورى الدولة (م.57 و61 و68 و69 من القانون المنفذ بالمرسوم 10434/1975).$q$,$q$[{"ar": "مذكرة خطية موجهة إلى رئيس البلدية تبيّن موضوع الشكوى وأسبابها والمطالب المحددة (تعويض أو إزالة ضرر)"}, {"ar": "ما يثبت الضرر أو القرار المشكو منه"}, {"ar": "إيصال أو إشعار بالاستلام يثبت تاريخ تقديم المذكرة"}, {"ar": "ما يثبت صفة صاحب العلاقة ومصلحته"}]$q$::jsonb,$q$[{"ar": "تحضير المذكرة بمطالب محددة (لا يشترط شكل معين ولا عبارات خاصة)"}, {"ar": "تسليمها إلى رئيس البلدية نفسه (لا إلى المحافظ) مقابل إيصال، ويُعتبر توجيهها إلى المحافظ صحيحًا إذا أحالها إلى البلدية"}, {"ar": "انتظار جواب الإدارة: قبول كلي أو جزئي أو رفض صريح، أو سكوت"}, {"ar": "عند الرفض الصريح أو الضمني: تقديم المراجعة إلى المرجع القضائي الإداري المختص ضمن المهلة"}, {"ar": "في الدعاوى أمام القضاء العدلي لا حاجة إلى هذه المذكرة (أُلغيت المذكرة التمهيدية)"}]$q$::jsonb,$q$رئيس البلدية (السلطة التنفيذية) — ثم مجلس شورى الدولة أو المحكمة الإدارية الخاصة$q$,null,$q$سكوت البلدية شهرين من تقديم المذكرة يُعدّ رفضًا ضمنيًا (بحسب الشارح) / مهلة المراجعة القضائية شهران من التبليغ أو العلم، وفي حال الرفض الضمني أربعة أشهر من تاريخ تقديم المذكرة (بحسب الشارح) / تتوقف المهلة بتقديم مراجعة إدارية تسلسلية، وتنقطع بمراجعة محكمة غير صالحة$q$ from municipal_service where slug=$q$t-299$q$ on conflict (service_id,version_no) do nothing;
