insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$مطالبة البلدية بالتعويض عن ضرر ناتج عن أشغال عامة أو مجارير أو رخصة بناء مخالفة$q$,$q$الفئة: اعتراضات وطعون. الأساس القانوني: م.إ. 118/1977 المواد 74 و100 و101؛ اجتهاد مجلس شورى الدولة (الشارح).$q$,$q$[{"ar": "مذكرة ربط نزاع تتضمن طلب التعويض (C3b-001)"}, {"ar": "تقرير فني أو كشف يثبت الضرر وسببه"}, {"ar": "نسخة عن رخصة البناء المشكو منها إن كان الضرر ناتجًا عن رخصة مخالفة للقانون"}, {"ar": "ما يثبت ملكية المتضرر أو صفته"}]$q$::jsonb,$q$[{"ar": "إثبات الضرر بكشف فني أو خبرة"}, {"ar": "تقديم مذكرة ربط النزاع إلى رئيس البلدية"}, {"ar": "عند الرفض أو السكوت: مراجعة القضاء الإداري الشامل (التعويض عن أضرار الأشغال العامة)"}, {"ar": "للبلدية حق الرجوع على الفاعل الأصلي أمام المحاكم العادية"}]$q$::jsonb,$q$رئيس البلدية — المحكمة الإدارية الخاصة ثم مجلس شورى الدولة (استئنافًا) أو القضاء العدلي بحسب طبيعة الفعل$q$,null,$q$مهل ربط النزاع والمراجعة كما في C3b-001 / سحب رخصة بناء مخالفة جائز خلال شهرين من صدورها قبل أن يكتسب الغير حقوقًا عليها (بحسب الشارح)$q$ from municipal_service where slug=$q$t-300$q$ on conflict (service_id,version_no) do nothing;
