insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الاعتراض على إنذار بهدم بناء (متداعٍ أو مخالف) أو بإخلائه$q$,$q$الفئة: اعتراضات وطعون. الأساس القانوني: م.إ. 118/1977 المادة 74؛ قانون البناء؛ نظام مجلس شورى الدولة.$q$,$q$[{"ar": "نسخة عن إنذار الهدم أو الإخلاء وما يثبت تاريخ تبليغه"}, {"ar": "تقرير مهندس أو خبير يبيّن إمكانية الإصلاح مع بقاء الشاغلين"}, {"ar": "رخصة البناء أو ما يثبت وضع البناء القانوني"}, {"ar": "مذكرة ربط نزاع إذا كان الطلب تعويضًا"}]$q$::jsonb,$q$[{"ar": "التأكد من تبليغ المالك والشاغلين الإنذار قبل أي هدم"}, {"ar": "تقديم اعتراض أو إصلاح ما يلزم خلال مهلة الإنذار"}, {"ar": "طلب وقف التنفيذ (تدبير تحفظي يمكن طلبه في أي مرحلة من الدعوى)"}, {"ar": "مراجعة مجلس شورى الدولة بطلب الإبطال والتعويض (يشترط ربط النزاع للتعويض)"}, {"ar": "بعد تنفيذ الهدم يقتصر الطلب على التعويض"}]$q$::jsonb,$q$رئيس البلدية (القرار والإنذار) — مجلس شورى الدولة (الطعن)$q$,null,$q$مهلة إنذار المالك بهدم بناء متداعٍ: خمسة عشر يومًا، وتُخفَّض إلى يومين عند الضرورة القصوى (بحسب الشارح) / مهلة مراجعة مجلس الشورى: شهران من التبليغ$q$ from municipal_service where slug=$q$t-301$q$ on conflict (service_id,version_no) do nothing;
