insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الإعلان عن وضع جداول التكليف قيد التحصيل وأداء الرسوم البلدية$q$,$q$الفئة: الرسوم والجباية. الأساس القانوني: قانون الرسوم البلدية 60/1988 المواد 102–107 و110–111.$q$,$q$[{"ar": "لا مستند مطلوب من المكلف لتأدية الرسم؛ يؤدى نقداً أو بحوالة بريدية أو بشك مصرفي لدى الجابي أو صندوق البلدية"}, {"ar": "إيصال الجابي أو الصندوق أو الحوالة البريدية (يعتمد تاريخه تاريخاً للدفع)"}]$q$::jsonb,$q$[{"ar": "تنظيم جداول التكليف الأساسية سنوياً على أساس وضع المكلف بتاريخ 31 كانون الأول من السنة السابقة"}, {"ar": "نشر الإعلان عن وضع الجداول قيد التحصيل (الجريدة الرسمية/صحيفتين يوميتين والإذاعة؛ ويمكن الاستعاضة عنه بالتعليق والإعلان المحلي للبلديات غير الخاضعة لقانون المحاسبة العمومية)"}, {"ar": "تأدية الرسم دفعة واحدة ضمن الأجل، أو التكليف الإضافي/التكميلي بالإبلاغ الشخصي"}, {"ar": "اعتراض المكلف لا يوقف التحصيل"}]$q$::jsonb,$q$رئيس السلطة التنفيذية في البلدية والمحتسب (الجابي)$q$,null,$q$شهران من اليوم التالي لنشر الإعلان أو لتبليغ التكليف الإضافي شخصياً / يمدد الأجل حكماً إلى أول يوم عمل إذا انتهى في عطلة / التكليف الإضافي/التكميلي ممكن حتى نهاية السنة الرابعة$q$ from municipal_service where slug=$q$t-307$q$ on conflict (service_id,version_no) do nothing;
