insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$الإنذار العام أو الشخصي للمكلف المتخلف عن دفع الرسوم البلدية$q$,$q$الفئة: الرسوم والجباية. الأساس القانوني: قانون 60/1988 المواد 109 و112.$q$,$q$[{"ar": "لا مستند من المكلف؛ الوثيقة الصادرة: إنذار عام (نشر) أو إنذار شخصي مبلغ"}]$q$::jsonb,$q$[{"ar": "انقضاء أجل الدفع دون سداد"}, {"ar": "توجيه إنذار عام ينشر في صحيفتين يوميتين وفي الإذاعة مرتين متتاليتين خلال عشرة أيام (ويمكن الاكتفاء بوسائل الإعلان المحلية للبلديات غير الخاضعة لقانون المحاسبة العمومية)"}, {"ar": "للمكلفين بتكليف إضافي أو تكميلي: إنذار شخصي، ويمكن للمجلس البلدي أن يقرر إنذاراً عاماً يقوم مقامه صراحة"}, {"ar": "تسديد المتوجب قبل انقضاء مهلة الإنذار يمنع الحجز"}]$q$::jsonb,$q$المحتسب المختص (الجابي) تحت إشراف رئيس البلدية$q$,null,$q$مهلة الإنذار تحدد في نص الإنذار ويحتسب بعدها الحجز (المهلة المحددة نصاً غير مستخرجة بدقة؛ تراجع المادة 112)$q$ from municipal_service where slug=$q$t-308$q$ on conflict (service_id,version_no) do nothing;
