insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$حجز أموال المكلف المتخلف عن الدفع وإغلاق محل عمله (تحصيل جبري)$q$,$q$الفئة: الرسوم والجباية. الأساس القانوني: قانون 60/1988 المواد 113–116؛ النموذج: قرار الحجز.$q$,$q$[{"ar": "لا مستند من المكلف؛ الوثائق الصادرة: قرار تكليف الموظف بتنفيذ الحجز وجدول بالرسوم والغرامات"}]$q$::jsonb,$q$[{"ar": "بعد انقضاء مهلة الإنذار: حجز أموال المكلف المنقولة وغير المنقولة أو إغلاق محل عمله إن لم يملك أموالاً تكفي"}, {"ar": "ترتيب الحجز: ديون المكلف لدى الغير (تحت يد الغير)، ثم المنقولة، ثم غير المنقولة"}, {"ar": "الحجز على المنقول بمعاونة المختار والقوى الأمنية وحفظ المحجوز في مكان يعينه المحتسب"}, {"ar": "الحجز على العقار: تبليغ الدائرة العقارية لوضع إشارة الحجز"}, {"ar": "حجز النقد تحت يد شخص ثالث (إيجارات، أجور)"}, {"ar": "تحديد ترتيب البيع بحيث يباع أولاً ما حرمان المكلف منه أخف ضرراً"}]$q$::jsonb,$q$المحتسب المختص بمعاونة المختار والقوى الأمنية$q$,null,$q$يبلغ المكلف قرار تنفيذ الحجز ويباشر التنفيذ خلال 48 ساعة من التبليغ (حسب نموذج القرار) / الإعلان عن بيع المنقول خلال أسبوعين من إلقاء الحجز$q$ from municipal_service where slug=$q$t-309$q$ on conflict (service_id,version_no) do nothing;
