insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$بيع الأموال المحجوزة بالمزاد العلني وحق المكلف في إلغاء المزايدة$q$,$q$الفئة: الرسوم والجباية. الأساس القانوني: قانون 60/1988 المواد 117–131.$q$,$q$[{"ar": "للمكلف الراغب بإلغاء المزايدة: ما يثبت تسديد كامل المبالغ المتوجبة وملحقاتها ونفقات الحجز والإعلان"}, {"ar": "للمشارك في المزايدة: كفالة وفق دفتر الشروط"}]$q$::jsonb,$q$[{"ar": "تصديق دفتر الشروط من رئيس لجنة البيع (يبين الأموال وأوصافها والقيمة المخمنة والسعر الأدنى وشروط الكفالة والدفع)"}, {"ar": "الإعلان في صحيفتين يوميتين على الأقل وتلصيق الإعلان مع ذكر موضوع المزايدة ومكانها وموعدها وتاريخ المزايدة الثانية"}, {"ar": "تقدير لجنة البيع القيمة التخمينية"}, {"ar": "المزايدة والإحالة المؤقتة ثم الإحالة النهائية"}, {"ar": "إن لم يتقدم مزايدون للعقار: إعادة طرحه بعد تخفيض السعر المخمن"}, {"ar": "تحميل المكلف نفقات الحجز والإعلان والمزايدة وحسمها من الحاصل؛ إيداع الفائض أمانة باسمه"}, {"ar": "نقل ملكية العقار إلى البلدية عند عدم وجود مزايدين مع إمكان استرداده بشروط (سنة)"}]$q$::jsonb,$q$لجنة البيع المعينة بقرار القائمقام أو المحافظ$q$,null,$q$إعلان المزايدة قبل موعدها 15 يوماً على الأقل / إعادة طرح العقار بين 30 و45 يوماً بعد التخفيض / الإعلان عن بيع المنقول خلال أسبوعين من الحجز$q$ from municipal_service where slug=$q$t-310$q$ on conflict (service_id,version_no) do nothing;
