insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$استرداد العقار المنقولة ملكيته إلى البلدية بسبب الرسوم (حق الاسترداد)$q$,$q$الفئة: الرسوم والجباية. الأساس القانوني: قانون 60/1988 المادة 131.$q$,$q$[{"ar": "طلب استرداد من المالك السابق"}, {"ar": "إيصالات تسديد كامل الرسوم والضمائم والغرامات والنفقات"}, {"ar": "إيصالات تسديد رسوم المدة التي سجل فيها العقار باسم البلدية"}, {"ar": "إيصالات ما أنفقته البلدية على صيانة العقار وتحسينه"}]$q$::jsonb,$q$[{"ar": "تسديد المتوجبات كاملة مع الفوائد القانونية"}, {"ar": "تسديد الرسوم عن مدة تسجيله باسم البلدية"}, {"ar": "تسديد نفقات الصيانة والتحسين التي أنفقتها البلدية"}, {"ar": "قرار البلدية بالتنازل/إعادة التسجيل وتنفيذه لدى السجل العقاري"}]$q$::jsonb,$q$رئيس البلدية والمجلس البلدي/أمين السجل العقاري$q$,null,$q$لا يمكن للبلدية بيع العقار قبل مرور سنة على تسجيله باسمها؛ وخلالها يحق للمالك السابق الاسترداد$q$ from municipal_service where slug=$q$t-311$q$ on conflict (service_id,version_no) do nothing;
