insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$تسديد الغرامة النقدية فوراً عن مخالفة الأنظمة البلدية الصحية والنظافة$q$,$q$الفئة: المعاملات ذات العلاقة بالصحة العامة. الأساس القانوني: قانون 12/6/1929 (الغرامات النقدية الفورية لمخالفات الأنظمة التي تصدرها السلطات البلدية) — المواد 1–7؛ القرار 227 تاريخ 7/7/1972 (تكليف قوى الأمن استيفاء الغرامة عن مخالفة الأنظمة البلدية الصحية والنظافة في المدن وقرى الاصطياف والاشتاء).$q$,$q$[{"ar": "محضر ضبط ينظمه الشخص المخوّل بالاستيفاء بمرسوم خاص"}, {"ar": "إيصال رسمي يقطعه منظم المحضر من دفتر ذي أرومة يحدد وزارة المالية شكله، يسلم للمخالف عند الدفع"}]$q$::jsonb,$q$[{"ar": "تنظيم محضر الضبط بالمخالفة من الشخص المخوّل (لا يجوز الاستيفاء الفوري إلا لمن عُيّن لهذا الغرض بمرسوم خاص)"}, {"ar": "تسديد الغرامة فوراً إلى منظم المحضر مقابل إيصال رسمي"}, {"ar": "إرسال المحضر إلى النيابة العامة في مكان المخالفة حتى بعد الدفع، ودعوة المخالف إلى توقيع الاعتراف بالمخالفة"}, {"ar": "تسديد الحد الأدنى فوراً يمنع ملاحقة النيابة العامة إلا إذا ترتب على المخالفة ضرر بالأشخاص أو الأموال أو كانت تكراراً"}, {"ar": "عند الامتناع عن الدفع يساق المخالف إلى قاضي الصلح المختص، ولا يوقف التنفيذ مراجعة أو اعتراض أو استئناف أو تمييز إذا اقتصرت العقوبة على غرامة"}]$q$::jsonb,$q$الدرك والشرطة (قوى الأمن الداخلي) المكلفون بالاستيفاء / قاضي الصلح / النيابة العامة$q$,null,null from municipal_service where slug=$q$t-322$q$ on conflict (service_id,version_no) do nothing;
