insert into service_source (version_id,title,kind) select v.id,$q$قانون 12/6/1929 (الغرامات النقدية الفورية لمخالفات الأنظمة التي تصدرها السلطات البلدية) — المواد 1–7؛ القرار 227 تاريخ 7/7/1972 (تكليف قوى الأمن استيفاء الغرامة عن مخالفة الأنظمة البلدية الصحية والنظافة في المدن وقرى الاصطياف والاشتاء)$q$,'law' from service_version v join municipal_service s on s.id=v.service_id where s.slug=$q$t-322$q$ and v.version_no=1 and not exists (select 1 from service_source z where z.version_id=v.id and z.title=$q$قانون 12/6/1929 (الغرامات النقدية الفورية لمخالفات الأنظمة التي تصدرها السلطات البلدية) — المواد 1–7؛ القرار 227 تاريخ 7/7/1972 (تكليف قوى الأمن استيفاء الغرامة عن مخالفة الأنظمة البلدية الصحية والنظافة في المدن وقرى الاصطياف والاشتاء)$q$);
