insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب إنشاء قناة ربط (مجرى) بالمجرى العام عبر ملك الغير — حق الارتفاق$q$,$q$الفئة: التنظيم المدني والبنية التحتية. الأساس القانوني: قانون 7/6/1937 المتعلق بحق الارتفاق المختص بالمجاري — المواد 1–10.$q$,$q$[{"ar": "طلب خطي من مالك العقار الذي لا يمكن ربطه بالمجرى العام إلا بالمرور في ملك الغير"}, {"ar": "مخطط قناة الربط وقياس ارتفاعها ومميزاتها لموافقة الدوائر البلدية المعنية"}]$q$::jsonb,$q$[{"ar": "تقديم الطلب إلى البلدية؛ يجب على مالك العقار المتوسط السماح بإنشاء القناة وصيانتها، ولا يجوز أن تخترق القناة المساحة المبنية من العقار (تستثنى جدران التصوينة)"}, {"ar": "موافقة الدوائر البلدية على تخطيط القناة وقياسها بعد الاستماع إلى مالك العقار المخترَق"}, {"ar": "رئيس البلدية، بطلب أحد الفريقين، يدعو أصحاب الشأن بكتاب مضمون للتفاوض الودي على التعويض؛ ولمحضر الاتفاق قيمة صك رسمي قابل للتنفيذ لدى دائرة الإجراء"}, {"ar": "إيداع المنتفع مبلغاً كافياً لنفقات الأشغال والأضرار المحتملة قبل التنفيذ؛ وعند الخلاف على الوديعة يعيّنها مؤقتاً رئيس البلدية"}, {"ar": "تنفيذ البلدية الأعمال وصيانتها على حساب المالك المنتفع، ولو جبراً بعد انقضاء مهلة التبليغ"}, {"ar": "عند الخلاف على التعويض ترفع الدعوى أمام المحكمة المختصة"}]$q$::jsonb,$q$البلدية (رئيس البلدية) / المحكمة المختصة عند الخلاف$q$,null,$q$دفع التعويض خلال 15 يوماً من جلسة الصلح (أو إيداعه خزينة الدولة في حال الرفض أو الحجز) / تنفيذ الأعمال ولو جبراً بعد 15 يوماً من تبليغ القرار الإداري الصادر عن البلدية$q$ from municipal_service where slug=$q$t-323$q$ on conflict (service_id,version_no) do nothing;
