insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إشعار استرداد عقار بلدي مؤجر لتنفيذ مشروع منفعة عامة (حقوق المستأجر)$q$,$q$الفئة: أملاك البلدية. الأساس القانوني: قانون 29/11/1955 (استرداد عقارات الدولة والبلديات المؤجرة) — المادة 1.$q$,$q$[{"ar": "قرار الاسترداد الصادر عن الوزير المختص ويحدد مهلة الإخلاء"}, {"ar": "إثبات إيداع التعويض الذي تحدده لجنة الاستملاك"}]$q$::jsonb,$q$[{"ar": "يصدر قرار استرداد العقار الخاص المأجور أو جزء منه عندما يكون إخلاؤه لازماً لتنفيذ مشروع معلن من المنافع العامة"}, {"ar": "يعيّن القرار مهلة الإخلاء"}, {"ar": "لا ينفذ القرار قبل إيداع التعويض الذي تحدده لجنة الاستملاك وفق أصول قانون الاستملاك ومبادئه"}]$q$::jsonb,$q$الوزير المختص / البلدية؛ لجنة الاستملاك (تحديد التعويض)$q$,null,$q$مهلة الإخلاء المحددة في القرار لا تقل عن 30 يوماً$q$ from municipal_service where slug=$q$t-324$q$ on conflict (service_id,version_no) do nothing;
