insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب إعفاء هبة مقدمة إلى البلدية من الرسوم$q$,$q$الفئة: المعاملات ذات العلاقة بالشؤون المالية. الأساس القانوني: المرسوم الاشتراعي 64 تاريخ 25/6/1977 — المادتان 1 و2.$q$,$q$[{"ar": "طلب إعفاء الهبة المقدمة إلى الإدارة أو المؤسسة العامة أو البلدية بقصد المساعدة، يقدم إلى وزارة المالية"}]$q$::jsonb,$q$[{"ar": "تعفى الهبات المقدمة إلى الإدارات العامة والمؤسسات العامة والبلديات بقصد المساعدة من جميع الرسوم، ولا سيما الجمركية والمالية والبلدية والمرفئية"}, {"ar": "يقدم طلب الإعفاء إلى وزارة المالية فيبت به الوزير أو المرجع الذي يعينه"}]$q$::jsonb,$q$وزارة المالية (الوزير أو من يعيّنه)$q$,null,null from municipal_service where slug=$q$t-325$q$ on conflict (service_id,version_no) do nothing;
