insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$تقديم تصريح الترشيح لعضوية المجلس البلدي أو لمنصب مختار/عضو مجلس اختياري$q$,$q$الفئة: معاملات عامة. الأساس القانوني: القانون 665/1997 (المواد 25 و26 للبلديات؛ 33 و35 للمختارين)؛ المرسوم الاشتراعي 118/1977 المواد 16 و28؛ قانون المختارين والمجالس الاختيارية 13/1/1928 المواد 7 و11؛ المادة 112 من قانون الدفاع الوطني (خدمة العلم).$q$,$q$[{"ar": "تصريح الترشيح مسجل لدى الكاتب العدل"}, {"ar": "بيان قيد إفرادي إلكتروني"}, {"ar": "سجل عدلي لا تتجاوز مدته شهراً واحداً"}, {"ar": "صورة عن قائمة الناخبين الواردة فيها اسم المرشح مصدقة من مقرر لجنة القيد"}, {"ar": "إثبات إيداع التأمين الانتخابي في صندوق المالية بالمحافظة أو القضاء (قيمته تحددها وزارة الداخلية — لم تُنقل)"}, {"ar": "ما يثبت أداء خدمة العلم أو الإعفاء منها (المرشح الذي لا يثبت ذلك ممنوع من الترشح)"}]$q$::jsonb,$q$[{"ar": "تسجيل تصريح الترشيح لدى الكاتب العدل ضمن المهلة المعلنة"}, {"ar": "تقديمه إلى مركز المحافظة أو القائمقامية مع المرفقات وإيداع التأمين في صندوق المالية"}, {"ar": "تنشر أسماء المرشحين المقبولة طلباتهم على باب البلدية (وأسماء المرشحين الاختياريين) سنداً للمادة 25 البند 5 من القانون 665/1997"}, {"ar": "الرجوع عن الترشح ضمن المهلة المحددة"}, {"ar": "إذا لم يبلغ عدد المرشحين لمنصب العضو الاختياري العدد المطلوب عند إقفال مدة الترشيح أو بسبب الرجوع جاز قبول ترشيحات جديدة تقدم قبل الاقتراع"}]$q$::jsonb,$q$وزارة الداخلية والبلديات — المديرية العامة للشؤون السياسية واللاجئين (مراكز المحافظات والأقضية)؛ كاتب العدل$q$,null,$q$مثال انتخابات 2025 في جبل لبنان: بدء الترشيح 4/4/2025، انتهاء الساعة 24:00 من 23/4/2025، انتهاء مهلة الرجوع عن الترشح 24:00 من 28/4/2025 (تحدد المهل لكل محافظة بقرار دعوة الهيئات الناخبة) / ترشيحات جديدة للعضو الاختياري عند نقص العدد: قبل الاقتراع بثلاثة أيام$q$ from municipal_service where slug=$q$t-326$q$ on conflict (service_id,version_no) do nothing;
