insert into service_source (version_id,title,kind) select v.id,$q$القانون 665/1997 (المواد 25 و26 للبلديات؛ 33 و35 للمختارين)؛ المرسوم الاشتراعي 118/1977 المواد 16 و28؛ قانون المختارين والمجالس الاختيارية 13/1/1928 المواد 7 و11؛ المادة 112 من قانون الدفاع الوطني (خدمة العلم)$q$,'law' from service_version v join municipal_service s on s.id=v.service_id where s.slug=$q$t-326$q$ and v.version_no=1 and not exists (select 1 from service_source z where z.version_id=v.id and z.title=$q$القانون 665/1997 (المواد 25 و26 للبلديات؛ 33 و35 للمختارين)؛ المرسوم الاشتراعي 118/1977 المواد 16 و28؛ قانون المختارين والمجالس الاختيارية 13/1/1928 المواد 7 و11؛ المادة 112 من قانون الدفاع الوطني (خدمة العلم)$q$);
