insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$التحقق من بيانات القيد على القوائم الانتخابية والحصول على نسخة منها$q$,$q$الفئة: معاملات عامة. الأساس القانوني: قانون الانتخاب (تثبيت القوائم الانتخابية سنوياً)؛ دليل الأسئلة العامة الفصل 11.$q$,$q$[{"ar": "طلب الحصول على قرص يتضمن قوائم الناخبين في القضاء أو المحافظة المختصة من المديرية العامة للأحوال الشخصية (الرسم المحدد بالدليل لم يُنقل)"}]$q$::jsonb,$q$[{"ar": "تثبّت القائمة الانتخابية في 31 آذار من كل عام ويمكن لأي شخص بعدها الحصول على نسخة من المديرية"}, {"ar": "القوائم غير متوافرة على الإنترنت بحسب الدليل (2010)؛ الحصول عليها بقرص من المديرية في بيروت"}, {"ar": "تدعو الوزارة الناخبين، قبل كل استحقاق، إلى التأكد من صحة بياناتهم قبل موعد نهائي يعلن (مثال: 1 آذار 2026)"}]$q$::jsonb,$q$وزارة الداخلية والبلديات — المديرية العامة للأحوال الشخصية$q$,null,$q$تثبيت القائمة الانتخابية: 31 آذار من كل عام / مثال 2026: آخر مهلة لتحديث/التأكد من البيانات الانتخابية 1 آذار 2026$q$ from municipal_service where slug=$q$t-327$q$ on conflict (service_id,version_no) do nothing;
