insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب إخراج القيد الإفرادي والعائلي إلكترونياً والحصول على مستند التعريف لبطاقة الهوية$q$,$q$الفئة: شهادات وإفادات. الأساس القانوني: تعاميم المديرية العامة للأحوال الشخصية (خدمة إخراج القيد الإلكتروني نيسان 2026؛ مستند التعريف تشرين الثاني 2026).$q$,$q$[{"ar": "النموذج الجديد لـ«طلب بيان القيد»"}, {"ar": "بطاقة الهوية (رقمها المؤلف من 12 رقماً وتاريخ إصدارها) لاستخراج مستند التعريف"}, {"ar": "إخراج قيد إفرادي إلكتروني صادر بعد 11 أيلول 2023 يحمل رمز QR لمسحه عند طلب مستند التعريف"}]$q$::jsonb,$q$[{"ar": "تقديم طلب إخراج القيد الإفرادي أو العائلي إلكترونياً؛ يمكن الحصول عليه للمرة الأولى من مكان القيد على أن يطلب لاحقاً من مكان السكن"}, {"ar": "للحصول على مستند التعريف: مسح رمز QR على إخراج القيد الإلكتروني ثم إدخال رقم الهوية وتاريخ إصدارها على المنصة وتحميل المستند وطباعته بعد التحقق"}, {"ar": "يستخدم المستند مرفقاً ببطاقة الهوية بدلاً من إخراج القيد الإفرادي في المعاملات التي تقبله لدى الإدارات العامة والمصارف"}]$q$::jsonb,$q$وزارة الداخلية والبلديات — المديرية العامة للأحوال الشخصية (أقلام النفوس)$q$,null,null from municipal_service where slug=$q$t-328$q$ on conflict (service_id,version_no) do nothing;
