insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$إبداء الاعتراض على طلب ترخيص مقلع أو كسارة ضمن النطاق البلدي$q$,$q$الفئة: إجراءات المحافظة على سلامة البيئة. الأساس القانوني: المرسوم 8803/2002 وتعديلاته (تنظيم المقالع والكسارات) — المادتان 7 و8.$q$,$q$[{"ar": "طلب الترخيص مع المستندات المحددة قانوناً يقدم إلى المحافظ (من صاحب الطلب)"}, {"ar": "اعتراض خطي يقدمه المواطن أو صاحب المصلحة إلى البلدية ضمن مهلة الإعلان"}]$q$::jsonb,$q$[{"ar": "يقدم طلب الترخيص إلى المحافظ ثم يحال إلى المجلس الوطني للمقالع في وزارة البيئة"}, {"ar": "تبلغ صورة عن الطلب إلى وزارة الداخلية والبلديات التي تحيلها إلى البلديات المختصة"}, {"ar": "تقوم البلدية بإعلام الجمهور عن الطلب وتتلقى الاعتراضات"}, {"ar": "يسقط الترخيص إذا لم يباشر العمل خلال سنة من إعطائه أو توقف الاستثمار أكثر من سنة"}]$q$::jsonb,$q$المحافظ؛ المجلس الوطني للمقالع (وزارة البيئة)؛ وزارة الداخلية والبلديات؛ البلدية المعنية$q$,null,$q$سقوط الترخيص: سنة من إعطائه دون مباشرة العمل، أو التوقف عن الاستثمار أكثر من سنة$q$ from municipal_service where slug=$q$t-329$q$ on conflict (service_id,version_no) do nothing;
