insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب حضور جلسة المجلس البلدي أو تقديم اقتراح إليه (مشاركة المواطن)$q$,$q$الفئة: المعاملات ذات الصفة الإدارية والقانونية والتنظيمية والتعاقدية. الأساس القانوني: المرسوم الاشتراعي 118/1977 — المادة 35 (لرئيس البلدية دعوة أي موظف أو شخص للاستماع إليه في جلسات المجلس) والمادة 45.$q$,$q$[{"ar": "طلب خطي إلى رئيس البلدية يتضمن الاقتراح أو سبب طلب الحضور"}]$q$::jsonb,$q$[{"ar": "قرارات المجلس يتخذها الرئيس والأعضاء في جلسة قانونية مكتملة النصاب بعد دعوة ومناقشة وبأكثرية الحاضرين"}, {"ar": "لا يمنع ذلك المواطن من تقديم مقترحات إلى المجلس البلدي وطلب السماح له بحضور الجلسات"}, {"ar": "يقرر رئيس البلدية دعوة المواطن للاستماع إليه خلال الجلسة (المادة 35)"}]$q$::jsonb,$q$رئيس البلدية / المجلس البلدي$q$,null,null from municipal_service where slug=$q$t-330$q$ on conflict (service_id,version_no) do nothing;
