insert into service_version (service_id,version_no,status,title_ar,summary_ar,documents,steps,authority_ar,fees,processing_time_ar) select id,1,'draft',$q$طلب الترخيص بمرأب أو موقف سيارات للعموم في ملك خاص (مؤسسة مصنفة)$q$,$q$الفئة: المعاملات ذات الصفة الاقتصادية. الأساس القانوني: المرسوم 4917/1994 (تعديل تصنيف المؤسسات الخطرة والمضرة بالصحة والمزعجة) — البند 170؛ المرسوم 21/1932؛ قانون الرسوم والعلاوات البلدية.$q$,$q$[{"ar": "طلب الترخيص مع المستندات اللازمة للمؤسسة المصنفة من الفئة الثانية أو الثالثة (محددة في الدليل البلدي)"}]$q$::jsonb,$q$[{"ar": "مرأب وقوف السيارات للعموم يعتبر مؤسسة مصنفة"}, {"ar": "إذا كانت مساحته أقل من 500 متر مربع يصنف من الفئة الثالثة ويقدم الطلب إلى القائمقام المختص"}, {"ar": "إذا زادت مساحته على 500 متر مربع يصنف من الفئة الثانية ويقدم الطلب في مكتب المحافظ"}]$q$::jsonb,$q$القائمقام (الفئة الثالثة) / مكتب المحافظ (الفئة الثانية)؛ البلدية$q$,null,null from municipal_service where slug=$q$t-332$q$ on conflict (service_id,version_no) do nothing;
